import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] tokens = br.readLine().split(" ");
        int n = Integer.parseInt(tokens[0]);
        int m = Integer.parseInt(tokens[1]);
        long totalCost = 0;

        if (n > 100) {
            int excessN = (n - 100) % 6;
            long quotientN = (n - 100) / 6;
            totalCost += quotientN * 6L * m;
            n = 100 + excessN;
        }

        if (m > 100) {
            int excessM = (m - 100) % 6;
            long quotientM = (m - 100) / 6;
            totalCost += quotientM * 6L * n;
            m = 100 + excessM;
        }

        int[][] grid = new int[n + 1][m + 1];
        int uLabel = 1;
        int vLabel = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if ((i + j) % 2 == 0) {
                    grid[i][j] = uLabel++;
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if ((i + j) % 2 != 0) {
                    grid[i][j] = vLabel++;
                }
            }
        }

        List<Integer>[] adjList = new ArrayList[uLabel];
        for (int i = 0; i < uLabel; i++) {
            adjList[i] = new ArrayList<>();
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if ((i + j) % 2 == 0) {
                    connect(grid, adjList, i, j, i - 3, j);
                    connect(grid, adjList, i, j, i - 2, j - 1);
                    connect(grid, adjList, i, j, i - 2, j + 1);
                    connect(grid, adjList, i, j, i, j - 3);
                    connect(grid, adjList, i, j, i - 1, j - 2);
                    connect(grid, adjList, i, j, i + 1, j - 2);
                    connect(grid, adjList, i, j, i, j + 3);
                    connect(grid, adjList, i, j, i - 1, j + 2);
                    connect(grid, adjList, i, j, i + 1, j + 2);
                    connect(grid, adjList, i, j, i + 3, j);
                    connect(grid, adjList, i, j, i + 2, j - 1);
                    connect(grid, adjList, i, j, i + 2, j + 1);
                }
            }
        }

        int maxMatchCount = maxMatching(adjList, uLabel - 1, vLabel - 1);
        totalCost += 2L * maxMatchCount;
        System.out.println(totalCost);
    }

    static void connect(int[][] grid, List<Integer>[] g, int i, int j, int s, int t) {
        int n = grid.length - 1;
        int m = grid[0].length - 1;
        if (s <= 0 || t <= 0 || s > n || t > m) return;
        g[grid[i][j]].add(grid[s][t]);
    }

    static int maxMatching(List<Integer>[] g, int m, int n) {
        int[] pairU = new int[m + 1];
        int[] pairV = new int[n + 1];
        int[] dist = new int[m + 1];
        Arrays.fill(pairU, 0);
        Arrays.fill(pairV, 0);
        int matchCount = 0;

        while (bfs(g, pairU, pairV, dist, m)) {
            for (int u = 1; u <= m; u++) {
                if (pairU[u] == 0 && dfs(g, u, pairU, pairV, dist))
                    matchCount++;
            }
        }
        return matchCount;
    }

    static boolean bfs(List<Integer>[] g, int[] pairU, int[] pairV, int[] dist, int m) {
        Queue<Integer> q = new LinkedList<>();
        for (int u = 1; u <= m; u++) {
            if (pairU[u] == 0) {
                dist[u] = 0;
                q.offer(u);
            } else {
                dist[u] = Integer.MAX_VALUE;
            }
        }
        int maxDist = Integer.MAX_VALUE;
        while (!q.isEmpty()) {
            int u = q.poll();
            if (dist[u] < maxDist) {
                for (int v : g[u]) {
                    if (pairV[v] == 0) {
                        maxDist = dist[u] + 1;
                    } else if (dist[pairV[v]] == Integer.MAX_VALUE) {
                        dist[pairV[v]] = dist[u] + 1;
                        q.offer(pairV[v]);
                    }
                }
            }
        }
        return maxDist != Integer.MAX_VALUE;
    }

    static boolean dfs(List<Integer>[] g, int u, int[] pairU, int[] pairV, int[] dist) {
        if (u != 0) {
            for (int v : g[u]) {
                if (pairV[v] == 0 || (dist[pairV[v]] == dist[u] + 1 && dfs(g, pairV[v], pairU, pairV, dist))) {
                    pairU[u] = v;
                    pairV[v] = u;
                    return true;
                }
            }
            dist[u] = Integer.MAX_VALUE;
            return false;
        }
        return true;
    }
}
